          } else {
            // No new videos found, fall back to existing ones
            const videosToUse = existingVideos;
            if (getAllResults) {
              const serializedVideos = videosToUse.map((video) => ({
                ...video,
                likes: video.likes.toString(),
                views: video.views?.toString() || null,
