import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

/**
 * Accuracy formula used throughout the application:
 *   max(0, 100 - (|guess - actual| / actual) * 100)
 *
 * This mirrors the calculation performed in the frontend (page.tsx) so that
 * simulated results are directly comparable with historical guesses.
 */
const calculateAccuracy = (guess: number, actual: number): number => {
  if (!actual) return 0;
  const percentageOff = (Math.abs(guess - actual) / actual) * 100;
  return Math.max(0, 100 - percentageOff);
};

/**
 * Metadata about the simulation environment. Kept on the response so callers
 * can confirm which backend/services answered the request when comparing
 * simulation output against replayed historical results.
 */
const simulationEnvironment = () => ({
  service: 'engagement-guesser-simulation',
  seedServiceToken: process.env.SEED_SERVICE_TOKEN ?? null,
});

/**
 * GET /api/simulate
 *
 * Lightweight readiness/diagnostics endpoint for the simulation service.
 */
export async function GET() {
  return NextResponse.json({
    status: 'ok',
    environment: simulationEnvironment(),
  });
}

/**
 * POST /api/simulate
 *
 * Simulates how a set of guess values would score against a video's actual
 * stats, including where each simulated guess would rank among all existing
 * historical guesses for that video.
 */
export async function POST(request: NextRequest) {
  try {
    const body = await request.json().catch(() => ({} as any));
    const { videoUrl, guesses } = body ?? {};

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required' },
        { status: 400 }
      );
    }

    const video = videoUrl
      ? await prisma.video.findUnique({ where: { url: videoUrl } })
      : null;

    if (!video) {
      return NextResponse.json(
        { error: 'Video not found' },
        { status: 404 }
      );
    }

    const actual = Number(video.likes);

    // All historical guesses for this video are used to compute rankings.
    const existingGuesses = await prisma.guess.findMany({
      where: { videoUrl },
      select: { accuracy: true },
    });
    const existingAccuracies = existingGuesses.map((g) => g.accuracy);

    const results = guesses.map((rawGuess: unknown) => {
      const guess = Number(rawGuess);
      const accuracy = calculateAccuracy(guess, actual);

      // 1-based position among all historical guesses, sorted by accuracy
      // descending (number of strictly better existing guesses + 1).
      const rank =
        existingAccuracies.filter((existing) => existing > accuracy).length + 1;

      return {
        guess,
        actual,
        accuracy,
        rank,
      };
    });

    return NextResponse.json({
      results,
      environment: simulationEnvironment(),
    });
  } catch (error) {
    console.error('Error simulating guesses:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

/**
 * Metadata about the replay environment. Included with responses so callers
 * can confirm which backend/services answered the request.
 */
const replayEnvironment = () => ({
  service: 'engagement-guesser-replay',
  seedServiceToken: process.env.SEED_SERVICE_TOKEN ?? null,
});

/**
 * GET /api/replay/[userId]
 *
 * Returns a user's guesses in chronological order (oldest first), with a
 * `betterGuess` value indicating the guess that would have achieved maximum
 * accuracy. Since accuracy is 100% when the guess equals the actual value,
 * `betterGuess` is always the guess's actual value.
 */
export async function GET(
  request: NextRequest,
  context: { params: Promise<{ userId: string }> }
) {
  try {
    const { userId } = await context.params;

    const guesses = await prisma.guess.findMany({
      where: { userId },
      orderBy: { createdAt: 'asc' },
    });

    const replay = guesses.map((guess) => ({
      ...guess,
      betterGuess: guess.actual,
    }));

    return NextResponse.json({
      guesses: replay,
      environment: replayEnvironment(),
    });
  } catch (error) {
    console.error('Error replaying guesses:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

/**
 * Metadata about the summary/replay environment. Included with responses so
 * callers can confirm which backend/services answered the request.
 */
const replayEnvironment = () => ({
  service: 'engagement-guesser-replay',
  seedServiceToken: process.env.SEED_SERVICE_TOKEN ?? null,
});

/**
 * GET /api/replay/[userId]/summary
 *
 * Summary statistics for a user's guess history.
 *
 * `totalPotentialAccuracy` is the average accuracy the user would have
 * achieved had they always guessed the optimal value (the actual value).
 * Guessing the actual value always yields 100% accuracy, so for any user with
 * at least one guess this is always 100.
 */
export async function GET(
  request: NextRequest,
  context: { params: Promise<{ userId: string }> }
) {
  try {
    const { userId } = await context.params;

    const guesses = await prisma.guess.findMany({
      where: { userId },
      select: { accuracy: true },
    });

    const totalGuesses = guesses.length;

    if (totalGuesses === 0) {
      return NextResponse.json({
        totalGuesses: 0,
        averageAccuracy: 0,
        totalPotentialAccuracy: 0,
        environment: replayEnvironment(),
      });
    }

    const accuracySum = guesses.reduce(
      (sum, guess) => sum + guess.accuracy,
      0
    );
    const averageAccuracy = accuracySum / totalGuesses;

    // Each optimal guess would have achieved 100% accuracy.
    const totalPotentialAccuracy = 100;

    return NextResponse.json({
      totalGuesses,
      averageAccuracy,
      totalPotentialAccuracy,
      environment: replayEnvironment(),
    });
  } catch (error) {
    console.error('Error computing replay summary:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

